interface MuxUICollectionItem {
  id?: string;
  key?: string;
  label?: React.ReactNode;
  value?: string;
  textValue?: string;
  disabled?: boolean;
  [key: string]: unknown;
}

type MuxUIAriaAccessibleName = {
  'aria-label': string;
  'aria-labelledby'?: never;
} | {
  'aria-label'?: never;
  'aria-labelledby': string;
};

type GridListItemOwnProps = {
  id: string;
  textValue?: string;
  disabled?: boolean;
};

type GridListItemProps = GridListItemOwnProps & {
  className?: string;
  style?: React.CSSProperties;
  children?: React.ReactNode;
};

type GridListOwnProps = {
  items?: MuxUIItems;
  selectedIds?: MuxUISelection;
  defaultSelectedIds?: MuxUISelection;
  disabled?: boolean;
  selectionMode?: 'none' | 'single' | 'multiple';
  onSelectionChange?: (ids: MuxUISelection) => void;
  onAction?: (item?: MuxUICollectionItem) => void;
  layout?: 'stack' | 'grid';
  orientation?: 'vertical' | 'horizontal';
};

type GridListProps = GridListOwnProps & {
  children?: React.ReactNode;
  style?: React.CSSProperties;
  className?: string;
} & MuxUIAriaAccessibleName;
